from pathlib import Path
import csv,json,hashlib
P=Path(__file__).resolve().parent
URL='https://www.trm.dk/media/cg1dxtrr/evaluering-af-forsoeg-paa-noerrebrogadepdf.pdf'
def sec(x):
 m,s=x.split(':');return int(m)*60+int(s)
bus=[('5A toward Nørreport AM','11:59','11:34',-15),('5A toward Nørreport PM','13:44','12:20',-84),('5A toward Bellahøj AM','11:20','11:07',-13),('5A toward Bellahøj PM','14:06','13:07',-59),('350S toward Nørreport AM','09:18','08:41',-37),('350S toward Nørreport PM','10:44','09:28',-76),('350S toward Bellahøj AM','09:06','08:51',-15),('350S toward Bellahøj PM','11:56','10:37',-79),('3A toward Enghave AM','04:37','05:16',39),('3A toward Enghave PM','05:09','05:31',22),('3A toward Nordhavn AM','05:34','04:45',-49),('3A toward Nordhavn PM','05:06','05:23',17)]
bike=[('A toward city AM','03:47','03:49'),('B toward city AM','03:32','03:25'),('A away from city AM','04:04','04:17'),('B away from city AM','03:19','03:57'),('A toward city PM','03:58','04:16'),('B toward city PM','03:25','03:29'),('A away from city PM','03:46','03:38'),('B away from city PM','03:17','03:35')]
for name,rows in [('bus',bus),('bike',bike)]:
 with (P/f'{name}-times.csv').open('w') as f:
  w=csv.writer(f);w.writerow(['label','before_seconds','after_seconds','calculated_change_seconds','source_printed_change_seconds','source_table'])
  for r in rows:w.writerow([r[0],sec(r[1]),sec(r[2]),sec(r[2])-sec(r[1]),r[3] if len(r)>3 else '', '5.4' if name=='bus' else '5.3'])
case={'id':'copenhagen-norrebrogade-2008','city':'Copenhagen','project':'Nørrebrogade 2008 trial','region':'Europe','eligibility':'Related bundled street reallocation. Road space was narrowed for cycling and motor access restricted; a uniform moving-lane removal count has not been certified. Keep outside the clean lane-conversion cohort.','status':'Original evaluation tables acquired','treatment':'Cycle space widening, two bus-only links, turn restrictions, stops and signal changes, and a bus-route change.','timing':'Trial began 1 October 2008. Bus GPS compares weeks 36–38 with 44–46; short adaptation window.','measurement':'Automatic bus running times for three routes; GPS cycling segment times; bicycle/vehicle counts and parallel-street diversion. Bus passenger totals were not resolved in this report.','identification':'Before/after evaluation, with seasonal cautions; no credible untreated comparison in the extracted running-time tables.','finding':'All eight 5A/350S route-period means fell by 13–84 seconds. Cycling segment means were mixed (−8 to +38 seconds); rerouted 3A also had mixed results.','limit':'Bus benefits cannot be assigned to bike lanes separately from bus priority and access restrictions. No matched total-person-flow or complete door-to-door time result. One printed bus difference is arithmetically inconsistent with its displayed means; corrected explicitly in our extract.','priority':'Useful bus and bike time benchmark','source_url':URL,'outcomes':['time','cycling']}
comps=[]
for cid,title,rows,sub in [('copenhagen-bus','Copenhagen: bus running time',bus[:8],'Routes 5A and 350S, weekday AM 08–10 / PM 15–18; September vs late October–November 2008.'),('copenhagen-bike','Copenhagen: cycling segment time',bike,'A: Bragesgade–Kapelvej. B: Kapelvej–Søtorvet. Before versus trial GPS runs; original Table 5.3.'),('copenhagen-rerouted-bus','Copenhagen: rerouted 3A bus time',bus[8:],'Route 3A changed its route during the trial. It is an outcome of the package, not an untreated control.')]:
 comps.append({'id':cid,'title':title,'subtitle':sub,'unit':'seconds','rows':[{'label':r[0],'before':sec(r[1]),'after':sec(r[2]),'change':sec(r[2])-sec(r[1]),'note':'Source prints −15 s, but 11:59 to 11:34 equals −25 s; displayed means retained.' if len(r)>3 and sec(r[2])-sec(r[1])!=r[3] else 'Segment running time; not a complete journey.'} for r in rows], 'note':'Descriptive before/after, no untreated comparator. The treatment bundles bus priority, cycle space, access and signal changes. Separate modes and route segments cannot establish total person-minutes.','source_url':URL})
(P/'candidates.json').write_text(json.dumps([case],ensure_ascii=False,indent=2))
(P/'comparisons.json').write_text(json.dumps(comps,ensure_ascii=False,indent=2))
(P/'source-audit.json').write_text(json.dumps({'url':URL,'checked_on':'2026-11-05','document':'COWI for Copenhagen, 8 December 2008','pdf_sha256':hashlib.sha256((P/'evaluation-2008.pdf').read_bytes()).hexdigest(),'tables':[{'table':'5.4','physical_pdf_page':30,'printed_page':28,'visual_check':True,'issue':'First row source prints -0:15 although displayed 11:59 -> 11:34 is -25 seconds. We recompute from displayed means.'},{'table':'5.3','physical_pdf_page':27,'printed_page':25}],'inference_limit':'No causal all-mode effect. Bike season adjustment cannot establish treatment effect; report explicitly says passenger change unresolved.'},indent=2))
print('Copenhagen extracted: 12 bus / 8 bike rows; one source arithmetic discrepancy flagged.')
